<template>
    <div id="app">
        <div class="login-btn">
            <el-button type="primary" @click="qrCodeLogin">扫码登陆</el-button>
        </div>
        <el-dialog
                title="使用IM APP扫一扫"
                :visible.sync="isQRCodeVisible"
                width="250px"
                :show-close="false"
                center
        >
            <div id="qrcode"></div>
        </el-dialog>
    </div>
</template>

<script>
  import QRCode from 'qrcodejs2'
  import axios from 'axios'
  import IOClientSDK from 'im-client-sdk';
  import { SSO_QRLOGIN } from 'im-client-sdk/dist/constant';



  export default {
    name: 'App',
    data(){
      return {
        isQRCodeVisible : false
      }

    },
    methods: {
      async qrCodeLogin() {
        let { data:{data:{device_id}} } = await axios.get('/api/qrCode')
        console.log(device_id);
        this.isQRCodeVisible = true
        this.$nextTick(()=>{
          let imgWrapper = document.getElementById('qrcode')
          imgWrapper.innerHTML = ''
          let qrcode = new QRCode(imgWrapper, {
            text: device_id,
            width: 200,
            height: 200,
          });
          // initialize a io client
          const instance = new IOClientSDK({
            url: '/sso', // nsp -> namespace
            query: {
              device_id,
            },
          });

          const socket = instance.getSocket();

          // overrides EventEmitter.on
          // https://socket.io/docs/client-api/#socket-on-eventName-callback
          socket.on(SSO_QRLOGIN, (resp) => {
            console.log(resp);
            instance.destroySocket();
            this.isQRCodeVisible = false
            this.$message({
              message: '登陆成功',
              type: 'success'
            });
          })
        })

      },
      initWebSocket() {
        const wsuri = 'wss://api.swbei.cn:9501/';
        this.websocket = new WebSocket(wsuri);
        this.websocket.onopen = this.websocketonsend;
        this.websocket.onmessage = this.websocketonmessage;
        this.websocket.onclose = this.websocketonclose;
      },
      websocketonsend(e) {
        this.websocket.send();
      },
      websocketonmessage(e) {
        var data = JSON.parse(e.data);
      },
      websocketonclose(e) {
        this.websocket.close();
      },

    },
    beforeDestroy() {
      //this.websocket.close();
    },
    components: {}
  }
</script>

<style lang="less" scoped>
    .login-btn {
        position: absolute;
        top: 50%;
        left: 50%;
        transform: translate(-50%, -50%);
    }
    #qrcode{
        text-align: center;
    }
</style>
